#include <string>
#include <algorithm>

class Solution {
public:
    int numberOfSubstrings(std::string s) {
        int last[3] = {-1, -1, -1};
        int ans = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            last[s[i] - 'a'] = i;
            ans += 1 + std::min({last[0], last[1], last[2]});
        }
        return ans;
    }
};

class Solution {
    public int numberOfSubstrings(String s) {
        int[] last = {-1, -1, -1};
        int ans = 0;
        for (int i = 0; i < s.length(); i++) {
            last[s.charAt(i) - 'a'] = i;
            ans += 1 + Math.min(last[0], Math.min(last[1], last[2]));
        }
        return ans;
    }
}

var numberOfSubstrings = function(s) {
    const last = [-1, -1, -1];
    let ans = 0;
    for (let i = 0; i < s.length; i++) {
        last[s.charCodeAt(i) - 97] = i;
        ans += 1 + Math.min(last[0], last[1], last[2]);
    }
    return ans;
};
